def passwordStrength(password):
    seen = set()   # characters already scored
    score = 0

    for ch in password:
        # Each distinct character is scored only once
        if ch in seen:
            continue
        seen.add(ch)

        if 'a' <= ch <= 'z':
            score += 1      # lowercase letter
        elif 'A' <= ch <= 'Z':
            score += 2      # uppercase letter
        elif '0' <= ch <= '9':
            score += 3      # digit
        else:
            score += 5      # special character from "!@#$"

    return score
